use xiom.io;

fn divide_safely(a: Float64, b: Float64) -> Result[Float64, Str] {
  if b == 0.0 {
    return Err("Division by zero");
  }
  return Ok(a / b);
}

fn pipeline(a: Float64, b: Float64, c: Float64) -> Result[Float64, Str] {
  let step1 = divide_safely(a, b)?;
  let step2 = divide_safely(step1, c)?;
  return Ok(step2);
}

fn main() -> Int {
  match pipeline(100.0, 5.0, 2.0) {
    Ok(val) => { return (val * 10.0) as Int; }
    Err(_) => { return -1; }
  }
}
